const raycaster=new THREE.Raycaster(),pointer=new THREE.Vector2();let walking=false,yaw=0,pitch=0,down=false,dragDistance=0,lastX=0,lastY=0,orbit=0,frame=0,lastTime=0,held='';const keys=new Set();
function showProduct(id){window.dispatchEvent(new CustomEvent('nutzora-product',{detail:id}))}
function resize(){const w=container.clientWidth,h=container.clientHeight;renderer.setSize(w,h,false);camera.aspect=w/h;camera.updateProjectionMatrix();if(!walking){const mobile=w<700;goal.set(mobile?15:12,mobile?10:8,mobile?23:15)}}new ResizeObserver(resize).observe(container);resize();
function enter(){walking=true;wrap.classList.add('walking');document.querySelector('.hero-copy').classList.add('hidden');goal.set(0,1.8,5.7);yaw=0;pitch=0;targetLook.set(0,1.65,-6);document.getElementById('sceneMode').textContent='WALK MODE';document.getElementById('sceneHint').innerHTML='↔ টেনে তাকান <span>·</span> তীরচিহ্ন / WASD দিয়ে হাঁটুন';wrap.scrollIntoView({behavior:'smooth',block:'center'})}
