renderer.domElement.addEventListener('pointerdown',e=>{down=true;dragDistance=0;lastX=e.clientX;lastY=e.clientY;renderer.domElement.setPointerCapture(e.pointerId)});
renderer.domElement.addEventListener('pointermove',e=>{if(!down){const r=renderer.domElement.getBoundingClientRect();pointer.set((e.clientX-r.left)/r.width*2-1,-(e.clientY-r.top)/r.height*2+1);raycaster.setFromCamera(pointer,camera);renderer.domElement.style.cursor=raycaster.intersectObjects(hitTargets).length?'pointer':'grab';return}let dx=e.clientX-lastX,dy=e.clientY-lastY;dragDistance+=Math.abs(dx)+Math.abs(dy);lastX=e.clientX;lastY=e.clientY;if(walking){yaw-=dx*.004;pitch=Math.max(-.4,Math.min(.4,pitch+dy*.003))}else{orbit=Math.max(-.65,Math.min(.65,orbit-dx*.004));const dist=container.clientWidth<700?27:19;goal.x=Math.sin(.66+orbit)*dist;goal.z=Math.cos(.66+orbit)*dist-1;}});
renderer.domElement.addEventListener('pointerup',e=>{if(dragDistance<8){const r=renderer.domElement.getBoundingClientRect();pointer.set((e.clientX-r.left)/r.width*2-1,-(e.clientY-r.top)/r.height*2+1);raycaster.setFromCamera(pointer,camera);const hits=raycaster.intersectObjects(hitTargets);if(hits[0])showProduct(hits[0].object.userData.product)}down=false});renderer.domElement.addEventListener('pointercancel',()=>down=false);
window.addEventListener('keydown',e=>{if(!walking||/INPUT|TEXTAREA/.test(document.activeElement.tagName)||document.querySelector('dialog[open]')||document.getElementById('cartDrawer').classList.contains('open'))return;if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight','w','a','s','d'].includes(e.key)){e.preventDefault();keys.add(e.key)}});window.addEventListener('keyup',e=>keys.delete(e.key));window.addEventListener('blur',()=>{keys.clear();held=''});
for(const b of document.querySelectorAll('[data-move]')){b.addEventListener('pointerdown',e=>{held=b.dataset.move;b.setPointerCapture(e.pointerId)});for(const ev of ['pointerup','pointercancel','lostpointercapture'])b.addEventListener(ev,()=>held='')}
function move(dir,dt){const speed=dt*2.8,dx=Math.sin(yaw),dz=-Math.cos(yaw);let x=goal.x,z=goal.z;if(dir==='forward'){x+=dx*speed;z+=dz*speed}if(dir==='back'){x-=dx*speed;z-=dz*speed}if(dir==='left'){x-=Math.cos(yaw)*speed;z-=Math.sin(yaw)*speed}if(dir==='right'){x+=Math.cos(yaw)*speed;z+=Math.sin(yaw)*speed}if(x>-4.8&&x<4.8&&z>-9.5&&z<7){const island=Math.abs(x)<2.5&&z>-5.65&&z<-2.9;const plinth=[-2.8,2.8].some(px=>Math.hypot(x-px,z-.2)<1.2);if(!island&&!plinth){goal.x=x;goal.z=z}}}
function animate(time){requestAnimationFrame(animate);if(document.hidden)return;const dt=Math.min((time-lastTime)/1000,.04);lastTime=time;if(walking){if(held)move(held,dt);for(const [key,dir] of [['w','forward'],['ArrowUp','forward'],['s','back'],['ArrowDown','back'],['a','left'],['ArrowLeft','left'],['d','right'],['ArrowRight','right']])if(keys.has(key))move(dir,dt);targetLook.set(goal.x+Math.sin(yaw)*7,1.65-pitch*6,goal.z-Math.cos(yaw)*7)}camera.position.lerp(goal,.065);look.lerp(targetLook,.065);camera.lookAt(look);renderer.render(scene,camera);if(frame++===2)document.getElementById('sceneLoader').classList.add('hidden')}
